TLM.f("Tempora/Pasc1-3",{"officium":"Feria Quarta infra Hebdomadam I post Octavam Paschæ","rule":["Oratio Dominica","Gloria","no Credo","Suffr=Maria3;Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo"],"fallback":"Tempora/Pasc1-0","from":{"Introitus":"Tempora/Pasc1-0","Oratio":"Tempora/Pasc1-0","Lectio":"Tempora/Pasc1-0","Graduale":"Tempora/Pasc1-0","Evangelium":"Tempora/Pasc1-0","Offertorium":"Tempora/Pasc1-0","Secreta":"Tempora/Pasc1-0","Communio":"Tempora/Pasc1-0","Postcommunio":"Tempora/Pasc1-0"},"sections":{"Introitus":[{"k":"ref","la":"1 Pet 2:2"},{"k":"text","la":"Quasi modo géniti infántes, allelúja: rationábiles, sine dolo lac concupíscite, allelúja, allelúja, allelúja."},{"k":"ref","la":"Ps 80:2"},{"k":"text","la":"Exsultáte Deo, adjutóri nostro: jubiláte Deo Jacob."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Quasi modo géniti infántes, allelúja: rationábiles, sine dolo lac concupíscite, allelúja, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut, qui paschália festa perégimus, hæc, te largiénte, móribus et vita teneámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Joánnis Apóstoli"},{"k":"ref","la":"1 Joannes 5:4-10"},{"k":"text","la":"Caríssimi: Omne, quod natum est ex Deo, vincit mundum: et hæc est victória, quæ vincit mundum, fides nostra. Quis est, qui vincit mundum, nisi qui credit, quóniam Jesus est Fílius Dei? Hic est, qui venit per aquam et sánguinem, Jesus Christus: non in aqua solum, sed in aqua et sánguine. Et Spíritus est, qui testificátur, quóniam Christus est véritas. Quóniam tres sunt, qui testimónium dant in cœlo: Pater, Verbum, et Spíritus Sanctus: et hi tres unum sunt. Et tres sunt, qui testimónium dant in terra: Spíritus, et aqua, et sanguis: et hi tres unum sunt. Si testimónium hóminum accípimus, testimónium Dei majus est: quóniam hoc est testimónium Dei, quod majus est: quóniam testificátus est de Fílio suo. Qui credit in Fílium Dei, habet testimónium Dei in se."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Matt 28:7"},{"k":"text","la":"In die resurrectiónis meæ, dicit Dóminus, præcédam vos in Galilǽam. Allelúja."},{"k":"ref","la":"Joannes 20:26"},{"k":"text","la":"Post dies octo, jánuis clausis, stetit Jesus in médio discipulórum suórum, et dixit: Pax vobis. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 20:19-31"},{"k":"text","la":"In illo témpore: Cum sero esset die illo, una sabbatórum, et fores essent clausæ, ubi erant discípuli congregáti propter metum Judæórum: venit Jesus, et stetit in médio, et dixit eis: Pax vobis. Et cum hoc dixísset, osténdit eis manus et latus. Gavísi sunt ergo discípuli, viso Dómino. Dixit ergo eis íterum: Pax vobis. Sicut misit me Pater, et ego mitto vos. Hæc cum dixísset, insufflávit, et dixit eis: Accípite Spíritum Sanctum: quorum remiséritis peccáta, remittúntur eis; et quorum retinuéritis, reténta sunt. Thomas autem unus ex duódecim, qui dícitur Dídymus, non erat cum eis, quando venit Jesus. Dixérunt ergo ei álii discípuli: Vídimus Dóminum. Ille autem dixit eis: Nisi vídero in mánibus ejus fixúram clavórum, et mittam dígitum meum in locum clavórum, et mittam manum meam in latus ejus, non credam. Et post dies octo, íterum erant discípuli ejus intus, et Thomas cum eis. Venit Jesus, jánuis clausis, et stetit in médio, et dixit: Pax vobis. Deínde dicit Thomæ: Infer dígitum tuum huc et vide manus meas, et affer manum tuam et mitte in latus meum: et noli esse incrédulus, sed fidélis. Respóndit Thomas et dixit ei: Dóminus meus et Deus meus. Dixit ei Jesus: Quia vidísti me, Thoma, credidísti: beáti, qui non vidérunt, et credidérunt. Multa quidem et ália signa fecit Jesus in conspéctu discipulórum suórum, quæ non sunt scripta in libro hoc. Hæc autem scripta sunt, ut credátis, quia Jesus est Christus, Fílius Dei: et ut credéntes vitam habeátis in nómine ejus."}],"Offertorium":[{"k":"ref","la":"Matt 28:2; 28:5-6"},{"k":"text","la":"Angelus Dómini descéndit de cœlo, et dixit muliéribus: Quem quǽritis, surréxit, sicut dixit, allelúja."}],"Secreta":[{"k":"text","la":"Súscipe múnera, Dómine, quǽsumus, exsultántis Ecclésiæ: et, cui causam tanti gáudii præstitísti, perpétuæ fructum concéde lætítiæ."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joannes 20:27"},{"k":"text","la":"Mitte manum tuam, et cognósce loca clavórum, allelúja: et noli esse incrédulus, sed fidélis, allelúja, allelúja."}],"Postcommunio":[{"k":"text","la":"Quǽsumus, Dómine, Deus noster: ut sacrosáncta mystéria, quæ pro reparatiónis nostræ munímine contulísti; et præsens nobis remédium esse fácias et futúrum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"a0ceefe3c3dc43e8":{"t":"1 Pt 2, 2, Ps 80, 2\n(1 Pt 2, 2) Kao novorođena djeca, <i>aleluja</i>,\nčeznite za čistim duhovnim mlijekom, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 80, 2) Kličite Bogu, pomoćniku našemu! Veličajte Boga Jakovljeva.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(1 Pt 2, 2) Kao novorođena djeca, <i>aleluja</i>,\nčeznite za čistim duhovnim mlijekom, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.","kn":"(I. Petr. 2, 2). Kao novorođena djeca aleluja, budite željni duhovnoga i čistoga mlijeka, aleluja., aleliuja, aleluja! (Ps. 80, 2). Radujte se Bogu, pomoćniku našemu, kličite Bogu Jakovljevu. Slava Ocu . . . Kao novorođena ...","knRef":"Kniewald 1942, str. 316–317 (snimka 159) (OCR)"},"1a8a41add174dc7e":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, da uskrsne svečanosti koje proslavismo po tvojoj darežljivosti zadržimo u vladanju i životu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Daj., molimo, svemogući Bože, da mi, koji proslaviismo uskrsne svetkovine, Tvojim ih darom zadržimo u vladanju i životu, po G. n.","knRef":"Kniewald 1942, str. 316–317 (snimka 159) (OCR)"},"f83f3d28d98d2efe":{"t":"1 Iv 5, 4-10\nČitanje Poslanice bl. Ivana apostola. Predragi, sve što je rođeno od Boga, pobjeđuje svijet. A ovo je pobjeda koja pobjeđuje svijet: naša vjera. Jer tko zapravo pobjeđuje svijet, ako ne onaj koji vjeruje da je Isus Sin Božji. Isus Krist je došao u vodi i u krvi, ne samo u vodi nego i u krvi. Ali svjedoči i Duh da je Krist istina. Jer trojica svjedoče na nebu: Otac i Riječ i Duh Sveti, i ova trojica su jedno. I troje svjedoči na zemlji. Duh i voda i krv, i ovo je troje jedno. Ako prihvaćamo svjedočanstvo ljudi, Božje je svjedočanstvo veće. A ovo je Božje svjedočanstvo, koje je veće, što je svjedočio za svog Sina. Tko vjeruje u Sina Božjega ima u sebi Božje svjedočanstvo.","kn":"Čitanje poslanice bi. Ivana apostola (I, 5, 4-10). Predragi! Sve što je rođeno od Boga, pobjeđuje svijet; naša vjera je ta pobjeda, koja pobjeđuje svijet. Tko je, koji pobjeđuje svijet, nego onaj, koji vjeruje, da je Isus Sin Božji? On je, koji je došao u vodi i krvi, Isus Krist: ne samo u vodi, nego u vodi i krvi. I Duh je, koji svjedoči, da je Krist istina. Jer su tri, koji svjedoče na nebu: Otac, Riječ i Duh Sveti, i ova su tri jedno. I troje je, što svjedoči na zemlji: duh i voda i krv; i ovo je troje jedno. Ako primamo svjedočanstvo ljudi, Božje je svjedočanstvo, koje je veće, da svjedoči za svoga Sina. Tko vjeruje u Božjega Sina, ima u sebi Božje svjedočanstvo.","knRef":"Kniewald 1942, str. 316–317 (snimka 159) (OCR)"},"d01d5bdd62a0c33d":{"t":"Mt 28, 7, Io 20, 26\n<i>Aleluja</i>, <i>aleluja</i>.\nNa dan svoga uskrsnuća kaže Gospodin: Ići ću pred vama u Galileju, <i>aleluja</i>.\nNakon osam dana, dok su vrata bila zatvorena, dođe Isus među svoje učenike i reče: Mir vama!, <i>aleluja</i>.","kn":"Aleluja, aleluja (Mt. 28, 7). U. dan svoga uskrsnuća ići ću pred vama u Galileju, veli. Gospodin, aleluja. (Iv. 20, 26).. Poslije osam dana dođe Isus, kad su vrata bila zatvorena i stade na sredinu među učenike svoje i reče: Mir vama., aleluja.","knRef":"Kniewald 1942, str. 318–319 (snimka 160) (OCR)"},"cc92cab110a8faad":{"t":"Iv 20, 19-31\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme: Uvečer prvoga dana po suboti, dok su bila zatvorena vrata gdje se bijahu sakupili učenici zbog straha od Židova, dođe Isus, stade usred njih i reče im: »Mir vama!« I kad to reče, pokaza im ruke i bok. Učenici se obraduju videći Gospodina. On ponovi: »Mir vama! Kao što je Otac poslao mene, tako i ja šaljem vas.« Kad to reče, dahnu u njih i reče im: »Primite Duha Svetoga. Kojima grijehe oprostite bit će oprošteni, a kojima zadržite bit će im zadržani.« – Toma, zvani Blizanac, jedan od dvanaestorice, nije bio s njima kad je došao Isus. Stoga mu ostali učenici rekoše: »Vidjeli smo Gospodina!« A on im odgovori: »Dok ne vidim na njegovim rukama rana od čavala i ne stavim svoj prst u mjesto od čavala i ne metnem svoju ruku u njegov bok, neću vjerovati.« – Poslije osam dana bili su ponovo njegovi učenici unutra, a s njima i Toma. Isus dođe, dok su vrata bila zatvorena, stade usred njih i reče: »Mir vama!« Zatim reče Tomi: »Stavi ovamo svoj prst i vidi moje ruke. Pruži svoju ruku i metni u moj bok. I ne budi nevjeran, nego vjeran.« Toma odgovori: »Gospodin moj i Bog moj!« Isus mu reče: »Toma, povjerovao si, jer si me vidio! Blago onima koji ne vide a vjeruju.« – Isus je pred svojim učenicima učinio još mnogo čudesa koja nisu zapisana u ovoj knjizi. Ova su zapisana, da vjerujete da je Isus Krist Sin Božji i da vjerujući u ime njegovo imate život.","kn":"t Slijedi sveto evanđelje po Ivanu (20, 19-31). U ono vrijeme uvečer prvoga dana po suboti, kad su od straha pred Židovima bUa zatvorena vrata, gdje su se bili sabrali učenici, dođe Isus, stade u sredinu i reče im: Mir vamal I kad ovo reče, pokaza im ruke i bok. A učenici se obradovaše videći Gosjpodina. Isus im opet reče: Mir vama! Kao što je Otac poslao mene, tako 1 ja šaljem vas. Kad to izreče, dahnu u njih i reče: Primite Duha Svetoga: kojima oprostite grijehe, bit će oprošteni, a kojima zadržite, bit će zadržani.^ A Toma Blizanac, jedan od dvanaestorice, nije bio s njima, kad je došao Isus. Drugi mu učenici reknu: Vidjeli smd Gospodina. On im odgovori: Ne ću vjerovati, dok ne vidim na njegovim rukama rana od čavala, i ne metnem isvoga prsta u mjesto čavala i ne metnem svoje ruke u njegov bok. I poslije osam dana, bili su opet njegovi učenici unutra i s njima Toma. Isus dođe dok su vrata bUa zatvorena, stade u sredinu i. reče: Mir Vamal Zatim kaže Tomi: Metni ovamo svoj prst, i vidi moje ruke, i pruži svoju ruku i metnl u moj bok, i ne budi nevjeran, nego vjeran! Toma odgovori: Gospodine moj i Bože moj I- 1 Tim riječima ustanovio je Isus tajnu pokore :i postavjo apostole i njihove nasljednike za duhovne suce. 2 Toma . poražen pada pred veličanstvom Uskrsnuloga te kratko i jezgrovito naglašuje Mesijansko i Božansko dostojanstvo Isusovo. I Isus mu reče: Povjerova-o si, kad si me vidio. 1 Blago onima, koji ne vide, a vjeruju! Isus je pred svojim učenicima učinib još mnogo drugih čudesa, koja nljesu napisana u ovoj knjizi. Ova su napisana, da vjerujete, da je Isus Krist Sin Božji, i po vjeri imate u njemu život.","knRef":"Kniewald 1942, str. 318–319 (snimka 160) (OCR)"},"09f7ca2203a3355a":{"t":"Mt 28, 2 i 5 i 6\nAnđeo Gospodnji siđe s neba i reče ženama: Onaj kojega tražite uskrsnuo je, kako je rekao, <i>aleluja</i>.","kn":"(Mt. 28, 2, 5, 6). Anđeo je Gospodnji sašao s neba i reče ženama; Uskrsnuo je -onaj, koga tražite, kako je rekao, aleluja.","knRef":"Kniewald 1942, str. 304–305 (snimka 153) (OCR)"},"7474f2043335fa3e":{"t":"Primi, molimo, Gospodine, darove Crkve koja klikće od radosti te daruj plod vječnoga veselja njoj kojoj si dao izvor tolike radosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, molimo, Gospodine, darove radosne Crkve i daruj joj plod vječnog veselja, jer si joj podao uzrok tolike radosti, po G. n.","knRef":"Kniewald 1942, str. 318–319 (snimka 160) (OCR)"},"1a0a565aa39e4fe3":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>u ovo</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"j Uistinu je dostojno i pravedno, pravo i spaso- I doba, ali osobito svečano na - današnji dan, (u ovo vrijeme), kad je žrtvovano naše vazmeno Janje, I Isukrst; jer On je pravo janje, koje je uzelo grijehe : svojim je uskrsnućem obnovio naš ž^vot. Zato pje- I vamo pjesmu Tvoje slave s anđelima i s arkanđe lima, s. prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"80c587002c599057":{"t":"Iv 20, 27\nPruži svoju ruku i upoznaj mjesto čavala, <i>aleluja</i>!\nI ne budi nevjeran, nego vjeran, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Iv. 20, 27). Pruži ruku svoju i upoznaj mjesta od čavala i ne budi nevjeran, nego vjeran, aleluja, aleluja.","knRef":"Kniewald 1942, str. 318–319 (snimka 160) (OCR)"},"2cfd55d0a790ab3e":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine Bože naš, daj da nam sveta otajstva, koja si ustanovio za naše spasenje, budu lijek i sada i ubuduće.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
